const calls = [];

const skyTarget = {
  __fake_lazy: true,
  __fake_calls: calls,
};

export const sky = new Proxy(skyTarget, {
  get(target, property, receiver) {
    if (property === "then") {
      return undefined;
    }
    if (property in target) {
      return Reflect.get(target, property, receiver);
    }
    if (typeof property !== "string") {
      return undefined;
    }
    return (...args) => {
      calls.push({ method: property, args });
      return { fake: true, method: property, args };
    };
  },
});
